class Solution {
    public int maxAbsoluteSum(int[] nums){
        int prefix=0,minimum=0,maximum=0;
        for(int value:nums){
            prefix+=value;
            minimum=Math.min(minimum,prefix);
            maximum=Math.max(maximum,prefix);
        }
        return maximum-minimum;
    }
}

code.kotlin:
class Solution {
    fun maxAbsoluteSum(nums:IntArray):Int{
        var prefix=0;
        var minimum=0;
        var maximum=0;
        for(value in nums){
            prefix+=value;
            minimum=minOf(minimum,prefix);
            maximum=maxOf(maximum,prefix)
        };
        return maximum-minimum
    }
}

